//! Edge-case integration tests for marks-rendering — generated by bug-hunter agent.
//!
//! Focus areas (recent fixes):
//! - Per-instance style overrides (opacity, stroke_width, fill_opacity) boundary values
//! - FillStroke field invariants when encoding produces NaN/Inf/extreme values
//! - SVG emission contracts for stroke-opacity, fill-opacity, angle, stroke-dasharray
//! - Numeric correctness of shape geometry (radius, path coordinates)
//! - SceneGraph serialization round-trip preserves per-instance style fields

#[cfg(test)]
mod tests {
    use ferrum_scene::{Color, FillStroke, PathCmd, SceneNode, StrokeStyle};

    // ── Per-instance opacity boundary values ─────────────────────────────

    #[test]
    fn fill_stroke_stroke_opacity_clamped_at_zero() {
        // stroke_opacity < 0.0 in source data should be clamped to 0.0 by the renderer.
        // At the scene-graph level, the value should already be clamped.
        let style = FillStroke {
            fill: Some(Color::rgb(100, 100, 100)),
            stroke: Some(Color::rgb(0, 0, 0)),
            stroke_width: 1.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 0.0, // minimum valid
            fill_opacity: 1.0,
            angle: 0.0,
        };
        assert!(style.stroke_opacity >= 0.0);
        assert!(style.stroke_opacity <= 1.0);
    }

    #[test]
    fn fill_stroke_stroke_opacity_clamped_at_one() {
        let style = FillStroke {
            fill: Some(Color::rgb(100, 100, 100)),
            stroke: Some(Color::rgb(0, 0, 0)),
            stroke_width: 1.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0, // maximum valid
            fill_opacity: 1.0,
            angle: 0.0,
        };
        assert!(style.stroke_opacity >= 0.0);
        assert!(style.stroke_opacity <= 1.0);
    }

    #[test]
    fn fill_stroke_fill_opacity_zero_is_valid() {
        // fill_opacity=0.0 means fully transparent fill — must not be treated as "omit".
        let style = FillStroke {
            fill: Some(Color::rgb(255, 0, 0)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 0.0,
            angle: 0.0,
        };
        assert_eq!(style.fill_opacity, 0.0);
        // Fill is still Some — the element exists; just transparent.
        assert!(style.fill.is_some());
    }

    #[test]
    fn fill_stroke_angle_negative_is_valid() {
        // Negative angles rotate counter-clockwise. Must be allowed.
        let style = FillStroke {
            fill: Some(Color::rgb(100, 100, 100)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: -45.0,
        };
        assert_eq!(style.angle, -45.0);
        assert!(style.angle.is_finite());
    }

    #[test]
    fn fill_stroke_angle_360_wraps_without_nan() {
        // 360-degree rotation is valid (equivalent to 0).
        let style = FillStroke {
            fill: Some(Color::rgb(100, 100, 100)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 360.0,
        };
        assert!(style.angle.is_finite());
    }

    // ── Stroke width boundary values ────────────────────────────────────

    #[test]
    fn fill_stroke_zero_stroke_width_with_stroke_color() {
        // Zero stroke_width with a stroke color is valid (invisible stroke, still specified).
        let style = FillStroke {
            fill: Some(Color::rgb(100, 100, 100)),
            stroke: Some(Color::rgb(0, 0, 0)),
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        };
        assert_eq!(style.stroke_width, 0.0);
        assert!(style.stroke.is_some());
    }

    #[test]
    fn stroke_style_width_must_not_be_negative() {
        // The renderer should never produce a negative width. Verify the constraint.
        let width = (-1.0_f64).max(0.0);
        let style = StrokeStyle {
            color: Color::rgb(0, 0, 0),
            width,
            opacity: 1.0,
            dash: None,
            stroke_cap: None,
            stroke_join: None,
            stroke_opacity: 1.0,
        };
        assert!(style.width >= 0.0, "stroke width must never be negative");
    }

    // ── NaN/Inf safety in derived geometry ──────────────────────────────

    #[test]
    fn radius_from_negative_area_is_nan_guard() {
        // If somehow a negative area value leaks through, sqrt produces NaN.
        // The renderer guards against this with `.max(default_radius)` fallback.
        let area = -100.0_f64;
        let r = (area / std::f64::consts::PI).sqrt();
        assert!(r.is_nan(), "sqrt of negative area must be NaN (renderer must guard)");
        // The guard pattern: use a default when computed radius is NaN.
        let default_radius = 3.0_f64;
        let safe_r = if r.is_finite() && r > 0.0 { r } else { default_radius };
        assert_eq!(safe_r, default_radius);
        assert!(safe_r.is_finite());
    }

    #[test]
    fn radius_from_inf_area_is_inf_guard() {
        // Infinite area should not produce Infinite radius in rendered output.
        let area = f64::INFINITY;
        let r = (area / std::f64::consts::PI).sqrt();
        assert!(r.is_infinite());
        // Guard: the renderer checks `is_finite()` on scale output, so Inf values
        // cause the row to be skipped before radius computation.
    }

    // ── Stroke dash pattern validation ──────────────────────────────────

    #[test]
    fn stroke_dash_empty_vec_means_solid() {
        // An empty dash vec means solid line (no dasharray emitted).
        let style = FillStroke {
            fill: None,
            stroke: Some(Color::rgb(0, 0, 0)),
            stroke_width: 1.0,
            opacity: 1.0,
            stroke_dash: Some(vec![]), // empty = solid
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        };
        // Implementation note: SVG emitter should check for empty and omit attribute.
        assert!(style.stroke_dash.as_ref().unwrap().is_empty());
    }

    #[test]
    fn stroke_dash_pattern_values_are_finite() {
        let pattern: Vec<f64> = vec![6.0, 3.0];
        for v in &pattern {
            assert!(f64::is_finite(*v), "dash pattern values must be finite");
            assert!(*v >= 0.0, "dash pattern values must be non-negative");
        }
    }

    // ── SceneNode serialization round-trip preserves new style fields ────

    #[test]
    fn scene_node_circle_serde_preserves_stroke_opacity() {
        let node = SceneNode::Circle {
            cx: 50.0,
            cy: 50.0,
            r: 5.0,
            style: FillStroke {
                fill: Some(Color::rgb(255, 0, 0)),
                stroke: Some(Color::rgb(0, 0, 0)),
                stroke_width: 1.5,
                opacity: 0.8,
                stroke_dash: None,
                stroke_opacity: 0.6,
                fill_opacity: 0.4,
                angle: 30.0,
            },
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Circle { style, .. } = &back {
            assert!((style.stroke_opacity - 0.6).abs() < 1e-10,
                "stroke_opacity lost in round-trip: got {}", style.stroke_opacity);
            assert!((style.fill_opacity - 0.4).abs() < 1e-10,
                "fill_opacity lost in round-trip: got {}", style.fill_opacity);
            assert!((style.angle - 30.0).abs() < 1e-10,
                "angle lost in round-trip: got {}", style.angle);
        } else {
            panic!("expected Circle node after round-trip");
        }
    }

    #[test]
    fn scene_node_rect_serde_preserves_fill_opacity() {
        let node = SceneNode::Rect {
            x: 10.0,
            y: 20.0,
            w: 50.0,
            h: 30.0,
            style: FillStroke {
                fill: Some(Color::rgba(100, 150, 200, 200)),
                stroke: None,
                stroke_width: 0.0,
                opacity: 1.0,
                stroke_dash: None,
                stroke_opacity: 1.0,
                fill_opacity: 0.7,
                angle: 0.0,
            },
            corner_radius: 3.0,
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Rect { style, corner_radius, .. } = &back {
            assert!((style.fill_opacity - 0.7).abs() < 1e-10);
            assert!((*corner_radius - 3.0).abs() < 1e-10);
        } else {
            panic!("expected Rect node after round-trip");
        }
    }

    #[test]
    fn scene_node_path_serde_preserves_stroke_dash() {
        let node = SceneNode::Path {
            commands: vec![
                PathCmd::MoveTo { x: 0.0, y: 0.0 },
                PathCmd::LineTo { x: 100.0, y: 100.0 },
                PathCmd::Close,
            ],
            style: FillStroke {
                fill: Some(Color::rgb(50, 50, 50)),
                stroke: Some(Color::rgb(200, 200, 200)),
                stroke_width: 2.0,
                opacity: 1.0,
                stroke_dash: Some(vec![5.0, 3.0, 1.0]),
                stroke_opacity: 0.9,
                fill_opacity: 1.0,
                angle: 0.0,
            },
            closed: true,
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Path { style, closed, .. } = &back {
            assert_eq!(style.stroke_dash.as_ref().unwrap(), &[5.0, 3.0, 1.0]);
            assert!((style.stroke_opacity - 0.9).abs() < 1e-10);
            assert!(*closed);
        } else {
            panic!("expected Path node after round-trip");
        }
    }

    // ── Polyline/StrokeStyle preserves stroke_opacity ────────────────────

    #[test]
    fn stroke_style_serde_preserves_stroke_opacity() {
        let node = SceneNode::Polyline {
            points: vec![(0.0, 0.0), (50.0, 50.0), (100.0, 0.0)],
            style: StrokeStyle {
                color: Color::rgb(0, 128, 255),
                width: 2.0,
                opacity: 1.0,
                dash: Some(vec![4.0, 2.0]),
                stroke_cap: None,
                stroke_join: None,
                stroke_opacity: 0.75,
            },
        };
        let json = serde_json::to_string(&node).unwrap();
        let back: SceneNode = serde_json::from_str(&json).unwrap();
        if let SceneNode::Polyline { style, .. } = &back {
            assert!((style.stroke_opacity - 0.75).abs() < 1e-10,
                "stroke_opacity lost: got {}", style.stroke_opacity);
            assert_eq!(style.dash.as_ref().unwrap(), &[4.0, 2.0]);
        } else {
            panic!("expected Polyline node after round-trip");
        }
    }

    // ── FillStroke default serde behavior: omit fields at default ────────

    #[test]
    fn fill_stroke_default_fields_omitted_in_json() {
        // When stroke_opacity=1.0, fill_opacity=1.0, angle=0.0, they should be
        // omitted from JSON (skip_serializing_if). This keeps scene-graph payloads compact.
        let style = FillStroke {
            fill: Some(Color::rgb(100, 100, 100)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 1.0,
            fill_opacity: 1.0,
            angle: 0.0,
        };
        let json = serde_json::to_string(&style).unwrap();
        assert!(!json.contains("stroke_opacity"),
            "stroke_opacity=1.0 should be omitted from JSON, got: {json}");
        assert!(!json.contains("fill_opacity"),
            "fill_opacity=1.0 should be omitted from JSON, got: {json}");
        assert!(!json.contains("angle"),
            "angle=0.0 should be omitted from JSON, got: {json}");
    }

    #[test]
    fn fill_stroke_non_default_fields_present_in_json() {
        let style = FillStroke {
            fill: Some(Color::rgb(100, 100, 100)),
            stroke: None,
            stroke_width: 0.0,
            opacity: 1.0,
            stroke_dash: None,
            stroke_opacity: 0.5,
            fill_opacity: 0.3,
            angle: 45.0,
        };
        let json = serde_json::to_string(&style).unwrap();
        assert!(json.contains("stroke_opacity"),
            "stroke_opacity=0.5 must be present in JSON, got: {json}");
        assert!(json.contains("fill_opacity"),
            "fill_opacity=0.3 must be present in JSON, got: {json}");
        assert!(json.contains("angle"),
            "angle=45.0 must be present in JSON, got: {json}");
    }
}
